"""Write-path batching study: 1,000,000 short lines, four write strategies."""
import hashlib
import os
import time

N_LINES = 1_000_000
BATCH = 10_000
OUTDIR = "bench_out"


def make_lines(n=N_LINES):
    return (f"line-{i:07d}-payload\n" for i in range(n))


def method1_line_buffered(path):
    # Line-buffered text mode; flush() -> write(2) per line.
    with open(path, "w", buffering=1) as f:
        for line in make_lines():
            f.write(line)


def method2_default_buffered(path):
    with open(path, "w") as f:
        for line in make_lines():
            f.write(line)


def method3_batches(path, batch=BATCH):
    buf = []
    with open(path, "w") as f:
        for line in make_lines():
            buf.append(line)
            if len(buf) >= batch:
                f.write("".join(buf))
                buf.clear()
        if buf:
            f.write("".join(buf))


def method4_single_join(path):
    with open(path, "w") as f:
        f.write("".join(make_lines()))


def sha256_file(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


METHODS = {
    1: ("line_buffered (buffering=1)", method1_line_buffered),
    2: ("default buffered", method2_default_buffered),
    3: (f"batched join ({BATCH}/chunk)", method3_batches),
    4: ("single giant join", method4_single_join),
}


def run(outdir=OUTDIR):
    os.makedirs(outdir, exist_ok=True)
    results = []
    hashes = {}
    for mid, (name, fn) in METHODS.items():
        path = os.path.join(outdir, f"out_m{mid}.txt")
        t0 = time.perf_counter()
        fn(path)
        dt = time.perf_counter() - t0
        hashes[mid] = sha256_file(path)
        results.append((mid, name, dt, os.path.getsize(path), hashes[mid]))
    return results, hashes


if __name__ == "__main__":
    results, _ = run()
    base = results[0][2]
    print(f"{'method':<30}{'seconds':>10}{'size':>14}  {'speedup':>7}")
    for mid, name, dt, size, _ in results:
        print(f"m{mid} {name:<27}{dt:>10.3f}{size:>14,}  {base / dt:>6.2f}x")

