import os
import shutil

import pytest

from io_bench import BATCH, N_LINES, OUTDIR, run

EXPECTED_LINE = b"line-0000000-payload\n"


@pytest.fixture(scope="module")
def bench():
    results, hashes = run()
    yield results, hashes
    shutil.rmtree(OUTDIR, ignore_errors=True)


@pytest.fixture(scope="module")
def hashes(bench):
    _, h = bench
    return h


def test_all_files_exist_and_sized(bench):
    results, _ = bench
    for mid, _, _, size, _ in results:
        p = os.path.join(OUTDIR, f"out_m{mid}.txt")
        assert os.path.exists(p)
        assert size == len(EXPECTED_LINE) * N_LINES


def test_hashes_identical_across_methods(hashes):
    vals = set(hashes.values())
    assert len(vals) == 1, f"output divergence: {hashes}"


def test_batched_or_single_beats_line_buffered_2x(bench):
    results, _ = bench
    times = {mid: dt for mid, _, dt, _, _ in results}
    best_batched = min(times[3], times[4])
    assert best_batched <= times[1] / 2.0, (
        f"batching not >=2x faster: m1={times[1]:.3f}s "
        f"best batched={best_batched:.3f}s"
    )

